﻿# Python code to generate the essay content

import random
import string

def generate_random_sentence(length):
    words = []
    for I in range(length):
        if I % 3 == 0:
            words.append(random.choice(string.uppercase))
        elif I % 3 == 1:
            words.append(random.choice(string.lowercase))
        else:
            words.append(random.choice(string.printable.replace('. ', '')))

    return ' '.join(words)

def generate_section(header, num_sentences):
    section = '{}:\n'.format(header)
    for I in range(num_sentences):
        section += '{}\n'.format(generate_random_sentence(random.randint(10, 20)))
    return section

def generate_intro(num_sentences):
    intro = 'В данном эссе мы рассмотрим разные способы, которыми технологии могут изменить строительную инициативу в ближайшие 10 лет, уходя в подробности влияющих факторов, преимуществ и потенциальных проблем для данного сектора.\n'

    intro += generate_random_sentence(random.randint(20, 40))
    intro += '\n'

    for I in range(num_sentences - 1):
        intro += '{}\n'.format(generate_random_sentence(random.randint(10, 20)))

    return intro

def generate_materials_section():
    return generate_section('Развитие строительных материалов', 4)

def generate_automation_section():
    return generate_section('Автоматизация строительства', 6)

def generate_robotics_section():
    return generate_section('Робототехника в строительной отрасли', 4)

def generate_3d_printing_section():
    return generate_section('3D-печать в области строительства', 3)

def generate_pros_cons_section():
    section = 'Преимущества и потенциальные проблемы внедрения технологий в строительную отрасль:\n'

    choose_pro_con = lambda: random.randint(1, 2)

    for I in range(random.randint(5, 10)):
        if choose_pro_con() == 1:
            section += '+ {}'.format(generate_random_sentence(random.randint(10, 20)))
        else:
            section += '- {}'.format(generate_random_sentence(random.randint(10, 20)))
        section += '\n'

    return section

def generate_conclusion():
    conclusion = 'Следует отметить, что прогностические рассуждения о будущем совершено сложно и однозначно дать ответ на вопросы наивысшей эффективности и последствий внедрения инновационных технологий в рамках строительной отрасли, однако налицо, что они уже сформированы в пласт	optirable опытно-конструкторских работ, и с ними необходимо будет поставить в ход проектирование современных и комфортных для людей построек, в согласии с правилами экологической безопасности. \n'

    choose_length = lambda: random.randint(10, 30)

    for I in range(random.randint(2, 4)):
        conclusion += '{}\n'.format(generate_random_sentence(choose_length()))

    return conclusion

def generate_complete_essay():
    intro_num_sentences = random.randint(6, 10)
    materials_section = generate_materials_section()
    automation_section = generate_automation_section()
    robotics_section = generate_robotics_section()
    printing_section = generate_3d_printing_section()
    pros_cons_section = generate_pros_cons_section()
    conclusion_num_sentences = random.randint(4, 6)

    essay = generate_intro(intro_num_sentences)
    essay += materials_section
    essay += automation_section
    essay += robotics_section
    essay += printing_section
    essay += pros_cons_section
    essay += generate_conclusion()

    return essay

print(generate_complete_essay())

