            'all_items'    => 'Все Новости событий',
            'menu_name'    => 'Новости событий',
        );

        public function __construct() {

            // Регистрация Custom Post Type в WordPress
            register_post_type(
                'your-custom-post-type',
                array(
                    'public' => true,
                    'label'  => __( 'Новости событий', 'your-plugin-name' ),
                    'labels' => self::$labels,
                    'menu_icon' => 'dashicons-calendar-alt',
                )
            );

            // Дополнительная настройка
            add_action( 'init', [$this, 'register_taxonomy'] );
        }

        public function register_taxonomy() {
            // Регистрация тегов (таксономии) для Custom Post Type
            register_taxonomy(
                'your-custom-post-type-tags',
                'your-custom-post-type',
                array(
                    'label' => __( 'Теги Новостей событий', 'your-plugin-name' ),
                    'hierarchical' => true,
                    'public' => true,
                    'show_admin_column' => true,
                    'show_ui' => true,
                    'query_var' => true,
                    'rewrite' => array( 'slug' => 'your-custom-post-type-tags' ),
                )
            );
        }

        // Остальные методы класса
        // ...

    }
    ```

