  // Информация для разделения на подмножества
  groupKey: String,
  // Параметры для расчета разнообразия и 5 важнейших признаков
  summary: Option[DistributionSummary],
  importantFeatures: Seq[(String, (Double, Double))]
)

class EnhancedBusinessDataProcessing(spark: SparkSession) {

  // Подготовка и обработка missing значений
  def fillNan(dict: Map[String, Dataset[Row]]): Map[String, Dataset[Row]] = {
    val filledDict = dict.map { case (key, ds) =>
      val columnNames = ds.select(StatisticalFunctions.col_names).as[String].first.toSeq
      val filledDs = fillNa(ds, Map(columnNames.head -> "mean"))
      key -> filledDs
    }
    filledDict
  }

  // Разделение на подмножества
  def groupBy(dict: Map[String, Dataset[Row]]): Map[String, Seq[GroupedBusinessData]] = {
    dict.map { case (groupKey, ds) =>
      val groupedDs = ds.groupBy(
        'industry, 'location
      ).agg(
        mean('revenue) as 'revenue,
        avg('age) as 'age,
        avg('employees) as 'employees,
        mean('profits) as 'profits
      )
      val summaries = groupedDs.map { groupedRow =>
        (groupedRow.as[GroupedBusinessData]
          .select('revenue, 'age, 'employees, 'profits, 'industry, 'location)
          .stats()
          .summary
        )
      }.collect()
      val importantFeatures = groupedDs.select(
        'revenue, 'age, 'employees, 'profits, 'industry
      ).describe('count, 'mean, 'stddev, 'skewness, 'kurtosis)
      .as[(String, (Double, Double))].rdd.map { row =>
        (
          row._1,
          (
            row._2.getDouble(1),
            row._3.getDouble(1)
          )
        )
      }.take(5)
      // Получение данных, необходимых для расчета разнообразия и 5 важнейших признаков
      groupKey -> groupedDs.map { row =>
        GroupedBusinessData(
          revenue = row.getAs[Double]("revenue"),
          age = row.getAs[Int]("age"),
          employees = row.getAs[Int]("employees"),
          profits = row.getAs[Double]("profits"),
          industry = row.getAs[String]("industry"),
          location = row.getAs[String]("location"),
          // Формирование необходимой информации для дальнейшего расчета
          groupKey = groupKey,
          summary = summaries.headOption,
          importantFeatures = importantFeatures
        )
      }.collect().toSeq
    }.toMap
  }

  def computeImportantFeatures(): Map[String, Seq[GroupedBusinessData]] = {
    // Обработка missing значений
    val filledDict = fillNan(spark.table("business_data").groupBy("industry", "location").agg(
        mean("revenue") as "revenue",
        avg("age") as "age",
        avg("employees") as "employees",
        mean("profits") as "profits"
      ).cache()
    )

    groupBy(filledDict)
  }
}

