   import scala.io.Source

   case class Business(data: Map[String, Any])

   def replaceMissingValues(data: Map[String, Any], colName: String): Map[String, Any] = {
     val colData = data.get(colName).asInstanceOf[Seq[Any]].toList
     val avgOrMedian = colData match {
       case Nil => 0.0   // если колонка пуста, запишем стандартное значение
       case _ =>
         val avg = colData.filter(_ != null).map(_.asInstanceOf[Double]).fold(0.0)(_ + _) / colData.filter(_ != null).map(_.asInstanceOf[Double]).size
         avg if avg % 1 == 0.0 else colData.median            // рассчитаем среднее или медиану в зависимости от целостности значений
     }
     val newValue = if (colData.exists(_ == null)) Some(avgOrMedian) else colData.headOption
     data.updated(colName, newValue)
   }

