       // Установите пороговый уровень на устранение отсутствующих значений
       val threshold = businesses.map(_.data(feature)).filter(_.isEmpty).size / businesses.size.toDouble

       businesses.flatMap {
         case Business(data) =>
           val missingValuesCount = data.filterKeys(_ == feature).values.filter(_ == null).size
           if (missingValuesCount / data.size >= threshold) {
             // При превышении порога обработайте отсутствующие значения
             val updatedData = businesses.flatMap {
