           (category, revenue / categoryBusinesses.size)
       }.toList

       val medianProfit = groupedByCategory.map {
         case (category, categoryBusinesses) =>
           val profit = categoryBusinesses.map {
             case Business(data) =>
               val revenue = data(feature).map(_ / 1_000.0).getOrElse(0)
               data("expenses").map(_ / 1_000.0).getOrElse(0) - revenue
           }.sortBy(_ == 0.0).drop(if (categoryBusinesses.size % 2 == 0) categoryBusinesses.size / 2 else categoryBusinesses.size / 2 + 1)
           (category, profit.headOption.getOrElse(0))
       }.toList

       val mostExpensiveItem = groupedByCategory.map {
         case (category, categoryBusinesses) =>
           val itemPrices = categoryBusinesses.flatMap {
             case Business(data) =>
               data.get("most_expensive_item_price").toList.map(_.toDoubleOrNull)
           }.sortedReverse
           (category, itemPrices.headOption.getOrElse(0))
       }.toList

       val avgAge = groupedByCategory.map {
