               data.get("year_established").toList.map(year => math.abs(year.toDoubleOrNull - System.currentTimeMillis() / 1000 / 365.25 / 86400 / 3600 / 24))
           }
           (category, years.sum / years.size)
       }.toList

       avgRevenue sortBy (_._2) take 5.zipWithIndex.map {
         case ((category, avgRevenue), rank) => (rank + 1, category, avgRevenue)
       } ++
         medianProfit zip mostExpensiveItem zip avgAge zip avgYearInBusiness
           .map {
             case ((category, medianProfit), (categoryExp, expensiveItemPrice), (avgAge, avgYearsInBusiness)) =>
               (category, categoryExp, medianProfit, expensiveItemPrice, avgAge, avgYearsInBusiness)
           }
           .sortBy(_._2)(Ordering[Double].reverse)
           .take(5)
           .zipWithIndex
           .map {
