// функция для вычисления стандартного отклонения числа в массиве
def calculateStandardDeviation(numbers: Array[Double]): Option[Double] = {
  if (numbers.nonEmpty) {
    val mean = numbers.sum / numbers.length
    math.sqrt(numbers.map(x => math.pow(x - mean, 2)).sum / (numbers.length - 1))
  } else None
}

// функция для вычисления информационной энтропии множества категорий
def calculateEntropy(categories: Array[String]): Option[Double] = {
  val occurrences: Map[String, Int] = categories.groupMap{_}.withDefaultValue(0)

  if (occurrences.size > 1) {
    val probabilities = occurrences.mapValues(_ / categories.length)

    -occurrences.values.map(p => p * math.log(p)).sum
  } else Some(0.0)
}

// функция для вычисления коэффициента вариационности массива чисел
def calculateCoefficientOfVariation(numbers: Array[Double]): Option[Double] = {
  calculateStandardDeviation(numbers).map(stdDev => stdDev / numbers.mean)
}

// функция для вычисления гини-индекса множества значений (средний результат для равномерно распределенного массива - 0.5)
def calculateGiniIndex(values: Array[Double]): Option[Double] = {
  val sortedValues = values.sorted

  (sortedValues.zipWithIndex.map { case (value, index) => (value, index + 1) }.foldLeft((0.0, 0.0)) { case ((prevSum, prevCount), (value, count)) =>
    val newSum = prevSum + value * count
    val newCount = prevCount + count

    (newSum, newCount)
  }) _._1 / (sortedValues.sum * sortedValues.length)

  // вычисление гини-индекса, если есть значения в массиве
  if (values.nonEmpty) Some(calculateGiniIndex(values)) else None
}

