    subset.groupMap(_.gender).values.toList.flatMap(_.headOption).count(_ != "unknown") / subset.length.toDouble,
    subset.map(_.educationLevel).distinct.map { level =>
      calculateEntropy(subset.filter(_.educationLevel == level))
    }.filterNot(_.isEmpty),
    subset.map(_.industryType).distinct.map(industry => {
      calculateGiniIndex(subset.filter(_.industryType == industry).map(_.businessSize))
    }).filterNot(_.isEmpty),
    subset.map(_.businessSize).filterNot(_isNaN).distinct.map { size =>
      calculateCoefficientOfVariation(subset.filter(_.businessSize == size).map(_.businessSize))
    }.filterNot(_.isEmpty)
  )
}

// основная функция для выполнения анализа разнообразия
def analyzeDataset(dataset: Array[BusinessOwner], features: Array[String]): (Array[Cluster[BusinessOwner]], Array[Array[Double]]) = {
  val featuresIndex = features.indices

  val clustererBuilder = ClusterAlgorithmBuilder[BusinessOwner]()
    .setClusterSpec(ClusterSpecollapsed)
    .setClusterSelector(ClusterSelectorkMeans)
    .setDistanceMetric(DistanceMetricBuilder.fromEuclideanDistance().build)
    .setClusterer(clusterer =>
      clusterer.cluster(dataset.toIndexedSeq)(_, _)
        .map(cluster => (clusterLifetime(cluster), cluster.getCenters.take(featuresIndex.map(_ => _)).map(_.toArray))))

  val (clusters, featureValues) = dataset.groupBy(_.apply(features.head)).map {
    case (key, values) =>
      val subset = values.toArray

      val result = analyzeSubsetData(subset, features)

      (result, subset.map(o =>
        featuresIndex.map(featureIndex =>
          o.productElement(featureIndex) match {
            case age: Double => age
            case gender: String => if (gender == "unknown") Double.NaN else 1
            case educationLevel: String => NaNDouble
            case industryType: String => NaNDouble
            case businessSize: Double => businessSize
          }
        )
      ))
  }.unzip

  (clusters, featureValues.flatMap(_._2))
}

