// Функция для чтения данных из источника в память с определенным типом данных
def readData(fileName: String)(implicit mf: Manifest[T]): Seq[T] = {
  val source = Source.fromFile(fileName)

  val records = source.getLines().toList.map(line => line.split(","))
    .map(parts => parts.map(part => {
      val fieldType = mf.erasure
      part match {
        case _: String => fieldType.getDeclaredFields().find(field => {
          field.getType == classOf[String]
        }).getDeclaredSetter().set(null, part)
        case _: Double => fieldType.getDeclaredFields().find(field => {
          field.getType == classOf[Double]
        }).getDeclaredSetter().set(null, part.toDouble)
        case _: Int => fieldType.getDeclaredFields().find(field => {
          field.getType == classOf[Int]
        }).getDeclaredSetter().set(null, part.toInt)
        case _ => throw new Exception(s"Unsupported field type: $part") // Выбросить исключение при обнаружении неподдерживаемого типа данных
      }
    }) : _*)
    .map(record => manifest[T].asInstanceOf[scala.reflect.BeanPropertyManifest[T]].fromBean(record.asInstanceOf[T]))

  source.close()
  records
}
