import scala.math.{abs, max, min}

case class OutliersStats(min: Double, max: Double, IQR: Double)

def calculateStats(data: Seq[Double]): (Double, Double, OutliersStats) = {
  val (sortedData, outliers) = data.partition(_ != Double.NaN)

  val n = sortedData.size
  val mean = sortedData.sum / n

  val median = if (n % 2 == 0) (sortedData(n / 2 - 1) + sortedData(n / 2)) / 2.0 else sortedData(n / 2)

