    private static final Map<String, Pattern> PATTERN_MAP = createPatterns();

    private static Map<String, Pattern> createPatterns() {
        Map<String, Pattern> patternMap = new HashMap<>();
        for (String category : CATEGORIES) {
            String regex = category.toLowerCase() + "(?:[^а-я]|_)+";
            patternMap.put(category, Pattern.compile(regex));
        }
        return patternMap;
    }

    public static void main(String[] args) {
        String[] flowers = {"Сиреневая сирень", "Маргаритки", "Бархатцы белые", "Желтая хризантема"};
        Map<String, ArrayList<String>> categoriesMap = analyzeFlowers(flowers);
        System.out.println(categoriesMap);
    }

    private static Map<String, ArrayList<String>> analyzeFlowers(String[] flowers) {
        Map<String, ArrayList<String>> categoriesMap = new HashMap<>();
        for (String flowerName : flowers) {
            String category;
            Pattern pattern;
            do {
                category = findCategory(flowerName);
                pattern = PATTERN_MAP.get(category.toLowerCase());
            } while (!pattern.matcher(flowerName.toLowerCase()).matches());
            ArrayList<String> flowerList = categoriesMap.containsKey(category) ? categoriesMap.get(category) : new ArrayList<>();
            flowerList.add(flowerName);
            categoriesMap.put(category, flowerList);
        }
        return categoriesMap;
    }

    private static String findCategory(String flowerName) {
        for (String category : CATEGORIES) {
            if (flowerName.toLowerCase().startsWith(category.toLowerCase())) {
                return category;
            }
        }
        char firstChar = flowerName.toLowerCase().charAt(0);
        switch (firstChar) {
            case 's': return "Сирень";
            case 'm': return "Маргаритки";
            case 'б', 'в': return "Бархатцы";
            case 'х', 'хр': return "Хризантема";
        }
        return null; // если в данном случае категория не найдена, может означать расхождение имен цветов и категорий
    }
}
```

