        case "Маргаритка" -> Optional.of("Маргаритка");
        case "Бархатцы" -> Optional.of("Бархатцы");
        case "Хризантема" -> Optional.of("Хризантема");
        default -> Optional.empty();
    };

    category.ifPresent(c -> {
        List<String> list = categories.getOrDefault(c, new ArrayList<>());
        list.add(flower);
