Ниже представлен расширенный пример программы на C#, реализующего условия, изложенные в задании:

```csharp
using System;

class Program
{
    static void Main()
    {
        string input = Console.ReadLine().ToLower(); // преобразуем ввод к нижнему регистру для нечувствительной обработки

        // 定义 перечисление с описанием редких и сложных эмоций
        enum RareEmotions
        {
            Schadenfreude,
            Ennui,
            Weltenschmerz,
            Naj　　　　// добавленное для примера, соответствующее чувству "нажда" (удовлетворение от преодоления трудностей) 
        }

        // Хэш-таблица для сопоставления ввода с названием эмоции
        Dictionary<string, RareEmotions> emotionsDictionary = new Dictionary<string, RareEmotions>()
        {
            {"schadenfreude", RareEmotions.Schadenfreude},
            {"ennui", RareEmotions.Ennui},
            {"weltschmerz", RareEmotions.Weltenschmerz},
            {"naj", RareEmotions.Naj}
        };

        // Поиск введенного чувства в словаре (используя нетривиальное название)
        bool emotionFound = emotionsDictionary.ContainsKey(GetEmotionName(input));

        if (emotionFound)
        {
