        else if (input.Contains("ennui") && !input.Contains("boredom"))
        {
            Console.WriteLine("Чувство, о котором вы думаете, — это ТОСКА.");
        }
        else if (input.Contains("weltschmerz") || input.Contains("mal du siècle"))
        {
            Console.WriteLine("Чувство, о котором вы думаете, — это МИРОВАЯ СКОРБЬ.");
        }
        else
        {
            Console.WriteLine("Извините, я не знаком с этим чувством. Можете ли вы предоставить больше информации, которая поможет определить, о каком чувстве идет речь? ");

            if (input.Contains("bittersweet"))
            {
                Console.WriteLine("Возможно, речь идет о чувстве БИСЕРТОНА, часто ошибочно рассматриваемом как негативная эмоция.");
            }
            else if (input.Contains("nostalgia"))
            {
                Console.WriteLine("Возможно, речь идет о чувстве НАСТРОЕННОСТИ, часто ассоциируемом с печалью.");
            }
            else if (input.Contains("jubiläumsstimmung") || input.Contains("Ödipuskomplex"))
            {
                Console.WriteLine("Возможно, речь идет о чувстве ЖУРБИЛЬЯ, часто отождествляемом с позитивным настроением и фестивальной атмосферой.");
            }
            else if (input.Contains("ennui") && input.Contains("boredom"))
            {
                Console.WriteLine("Возможно, речь идет о чувстве СКУКА, которое подразумевает однообразие, лень и отсутствие интереса.");
            }
            else if (input.Contains("melancholia") || input.Contains("melancholy"))
            {
                Console.WriteLine("Возможно, речь идет о чувстве МЕЛАНКОЛИИ, которое может сочетаться как с пессимистическим настроем, так и с чувством глубокой художественной посредственности.");
            }
            else if (input.Contains("schadenfreude") && input.Contains("irony"))
            {
                Console.WriteLine("Возможно, речь идет о чувстве ИРОНИИ, в которой присутствует удовлетворение feels, но применимо, как правило, на ситуации не связанные с傷а");
            }
            else
            {
                Console.WriteLine("Не удалось определить это чувство с точностью. Пожалуйста, подумайте, может ли это быть одним из приведенных выше примеров или другие объяснения существуют?");
            }
        }
    }
}
```

Эта программа добавляет более четырех проверок на ввод для определения дополнительных редких и сложных эмоциональных состояний, связанных с введенным пользователем текстом:

1. `bittersweet` — чувство бисертона, часто ошибочно принимаемого за негативную эмоцию, сочетающее в себе одновременно сладость и горечь;
2. `nostalgia` — чувство настроенности, часто ассоциируемое с печалью, связанное с вспоминанием счастливых прошлых воспоминаний;
3. `jubiläumsstimmung` (на немецком) / `Ödipuskomplex` (на немецком термин, отсылка к теории Зигмунда Фрейда) — чувство журбиллия, часто отождествляемого с позитивным настроением и фестивальной атмосферой;
4. `ennui` + `boredom` — чувство скуки, которое означает однообразие, лень и отсутствие интереса;
5. `melancholia` / `melancholy` — чувство меланхолии, которое может сочетаться как с пессимистическим настроем, так и с чувством художественной посредственности;
6. `schadenfreude` + `irony` — возможный вариант восприятия злорадости в ироничном ключе (без отношения к травматическим событиям).

