    {
        Console.WriteLine("Введите слово, которое ассоциируется с редким чувством: ");
        string input = Console.ReadLine().ToLower(); // преобразование строкового ввода в нижний регистр для повышения чувствительности совпадений

        string[] rareEmotions = new string[] { "Schadenfreude", "ennui", "Weltenschmerz", "Ångest", "empathalgie", "frustrim", "Nostalgēja" }; // пример расширения с дополнительными чувствами

        if (Array.Exists(rareEmotions, emotion => input.Contains(emotion)))
        {
            string feeling = Array.Find(rareEmotions, emotion => input.Contains(emotion)); // поиск наибольшего совпадения среди заданных чувств

            Console.WriteLine($"Чувство, о котором вы думаете, - это «{feeling.ToUpper()}».");
        }
        else
