   import xml.etree.ElementTree as ET

   def read_cube_from_xml(xml_path):
       # Read XML
       tree = ET.parse(xml_path)
       root = tree.getroot()

       cube = RubikCube()

       # Check for the expected structure of XML
       xml_faces = root.findall('.//face')   # receiving XML nodes for all faces
       assert len(xml_faces) == 6, f"Expecting 6 faces in XML, but {len(xml_faces)} are found"

       for i, xml_face in enumerate(xml_faces):
           # Check the number of subelements
           assert len(xml_face) == 4, f"Expecting 4 child nodes for face {i}, but {len(xml_face)} are found"
           cube.faces[i] = Face(
               int(xml_face.find('./center-piece').text),
               [int(child.text) for child in xml_face.findall('./edge-pieces/edge-piece')]
           )

       return cube
