   const fs = require('fs');

   function readCubeFromXml(xmlPath) {
     // Read XML
     const xmlContent = fs.readFileSync(xmlPath, 'utf8');
     const xmlParse = new DOMParser().parseFromString(xmlContent, 'text/xml');

     const cube = new RubikCube();

     // Check for the expected structure of XML
     const xmlFaces = xmlParse.getElementsByTagName('face');
     const numFaces = xmlFaces.length;
     if (numFaces !== 6) {
       throw new Error(`Expecting 6 faces in XML, but ${numFaces} are found`);
     }

     for (let I = 0; I < numFaces; i++) {
       const xmlFace = xmlFaces[i];

       // Check the number of subelements
       const xmlFaceChildren = Array.from(xmlFace.childNodes);
       const numFaceChildren = xmlFaceChildren.length;
       if (numFaceChildren !== 4) {
         throw new Error(`Expecting 4 child nodes for face ${i}, but ${numFaceChildren} are found`);
       }

       cube.faces[i] = new Face(
         parseInt(xmlFace.children[0].textContent),
         xmlFace.children[1].getElementsByTagName('edge-piece')
           .map(xmlEdgePiece => parseInt(xmlEdgePiece.textContent))
           .slice(0, 3)
       );
     }

     return cube;
   }
