Для начала нам понадобится установленный Node.js и Express.js. В настройках веб-сервера мы будем использоваться машинописный текст, поэтому нам также понадобится некоторая дополнительная библиотека для преобразования текста в HTML для отображения в браузере.

Предположим, что у нас есть один роут `/transform-text` с методом GET и один роут `/original-text` с методом GET для получения исходного текста и модели преобразования текста.

1. Создайте новый файл, например `server.js`, и загрузите следующие зависимости:

```javascript
const express = require('express');
const fs = require('fs');
const transformTextToHtml = require('transform-text-to-html'); // example library for transforming text to HTML
const app = express();
```

2. Настройте веб-сервер:

```javascript
const PORT = process.env.PORT || 5000;

app.use(express.static('public')); // serve static assets from the 'public' folder (optional)

app.get('/', (req, res) => {
  res.sendFile(__dirname + '/index.html');
});

app.get('/original-text', (req, res) => {
  res.sendFile(__dirname + '/original-text.txt');
});

app.get('/transform-text', (req, res) => {
  const originalText = fs.readFileSync(__dirname + '/original-text.txt', 'utf8');

  const transformedText = transformTextToHtml(originalText);

  res.send(transformedText);
});

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

