        &= \frac{B_0}{\sqrt{1 + 2b \cos(2\omega t + \theta_0) + b^2}} \\
    b
        &= \frac{B_0^2 (1 - \cos(\theta_0))}{2}
\end{align}
\begin{align}
    \theta(t)
        &= \theta_0 + \arcsin\left(\frac{1 - b \cos(2\omega t + \theta_0)}{1 + b^2 - 2b\cos(2\omega t + \theta_0)}\right)
\end{align}

