\section{Пример решения задачи управления портфелем активов}

\begin{frame}
  \frametitle{Задача управления портфелем активов}
  Обозначения:
  \begin{itemize}
    \item $N$ --- количество ценных бумаг в портфеле.
    \item $x_k(t) \geq 0$ --- количество акций $k$-й ценной бумаги в момент времени $t$.
    \item $r_k$ --- ежегодный доходность акций $k$-й ценной бумаги.
    \item $q_k$ --- ежемесячный дивиденд акций $k$-й ценной бумаги.
    \item $c_k(t)$ --- цена одной акции $k$-й ценной бумаги в момент времени $t$.
    \item $\mu$ --- предполагаемая оценка бесплатной доходности денег.
  \end{itemize}

  Пусть стремясь к максимальной будущей стоимости портфеля $J$ на заданный интервал времени $[0,T]$, необходимо решить задачу оптимального управления:
  \begin{equation*}
    \begin{aligned}
      J(x,\mathbf{u}) &= \mathbb{E}\left[ \exp\left\{ -\int_0^T r(t) dt + \mu \int_0^T \frac{du(t)}{u(t)} dt \right\} \prod_{k=1}^N (x_k(T))^{q_k} \right] \\
      s(t) &= \mathbf{A}(t)s(t) + \mathbf{b}(t),\quad s(0) = s_0 \\
      x_k(t) &= s_k(t),\quad k = 1,\ldots,N \\
      \dot{u}(t) &= u(t)\left( r(t) - \mathbf{c}(t)^\intercal \mathbf{A}(t) s(t) - \mu \right),\quad u(0) = 1 \\
      \mathbf{c}(t) &= \begin{pmatrix} c_1(t) \\ \vdots \\ c_N(t) \end{pmatrix},\quad \mathbf{A}(t) = 
      \begin{pmatrix}
        - \sum_{j=1}^N a_{1j}(t) & \cdots & -a_{1N}(t) \\
        \vdots & \ddots & \vdots \\
        -a_{N1}(t) & \cdots & -\sum_{j=1}^N a_{Nj}(t)
      \end{pmatrix} \\
      \mathbf{b}(t) &= \begin{pmatrix} b_1(t) \\ \vdots \\ b_N(t) \end{pmatrix},\quad r(t) = \mathbf{c}(t)^\intercal \mathbf{b}(t) \\
      \mathbf{u}(t) &= \begin{pmatrix} u_1(t) \\ \vdots \\ u_N(t) \end{pmatrix},\quad \dot{x}(t) = \mathbf{A}(t) x(t) + \mathbf{b}(t) \\
      \text{минимизация:} & J^* = \max_{\mathbf{u}(\cdot) \in \mathcal{U}} J(x^*,\mathbf{u})
    \end{aligned}
  \end{equation*}
  Где:
  \begin{itemize}
    \item $s(t)$ --- вектор концентраций акций портфеля.
    \item $x_k(t)$ --- численность акций $k$-й ценной бумаги на момент времени $t$.
    \item $\mathbf{u}(t)$ --- вектор цена одной акции в момент времени $t$.
    \item $\mathcal{U}$ --- класс управлений $\mathbf{u}(t)$ для $t \in [0,T]$.
    \item $\mathbf{A}(t)$ --- матрица переходов вектора $s(t)$.

