def format_date_iso_to_str(date_str):
    """Функция для преобразования формата даты ISO в строку 'YYYY-MM-DDTHH:MM:SSZ'."""
    date_obj = datetime.datetime.strptime(date_str, '%Y-%m-%dT%H:%M:%SZ')
