3. Скопируйте и вставьте следующее содержимое для вашего пользовательского правила в `rules`:

```javascript
const { callExpression, memberExpression, JSXClosingElement } = require('@babel/types');

const HOOK_METHODS = ['beforeCreate', 'created', 'beforeMount', 'mounted', 'beforeUpdate', 'updated', 'activated', 'deactivated', 'beforeDestroy', 'destroyed'];


module.exports = {
  meta: {
    docs: {
      description:
        'Prevent mutating state in methods of Vue.js\'s new lifecycle hooks and avoid calling other state-changing methods',
      category: 'Possible Errors',
      recommended: true,
    },
    fixable: 'code',
  },

  create(context) {

    function isLifecycleHookMethod(node) {
      const { type, key } = node;
      return type === 'MemberExpression' && HOOK_METHODS.includes(key.name);
    }

    function isStateChangingMethodCall(node) {
      const { callee } = node;
      const name = callee?.object?.property?.name;

      // проверяем, содержит ли вызываемая функция вкусный список
      // иSnackBar, modal, и т.д.
      const isStateChangingFunction = [
        'push',
        'pop',
        'shift',
        'unshift',
        'splice',
        'sort',
        'reverse',
        'push',
        'splice',
        'unshift',
        'set',
        '$forceUpdate',
        '$set',
        '$watch',
        '$nextTick',
        '$emit',
      ].includes(name || '');

      const parent = node.parent;

      return (
        isStateChangingFunction &&
        (parent.type === JSXClosingElement ||
          (parent.type === 'CallExpression' && isLifecycleHookMethod(parent.callee)))
      );
    }

    return {
      CallExpression(node) {
        if (isLifecycleHookMethod(node.callee)) {
          const methods = node.arguments.reduce((acc, arg) => {
            if (memberExpression(arg)) {
              acc.push(...[...Array.from(arg.properties)].map(({ key }) => key.name));
            }
            return acc;
          }, []);

          if (methods.some((method) => isStateChangingMethodCall(callExpression(node, ['callee', 'arguments'])))) {
            context.report({
              node,
              message:
                '`{{ method }}` method cannot directly or indirectly modify component state in lifecycle hook `{{ lifecycleHook }}`',
              data: {
                method: methods.join(', '),
                lifecycleHook: node.callee.object.property.name,
              },
              fix(fixer) {
                return fixer.removeRange(node.range);
              },
            });
          }
        }
      },
    };
  },
};
```

