В данном примере устанавливается плагин `vue-eslint-parser`, который парсит файлы `.vue` как комбинацию `JSX` и `vue-template-compiler`. Он также принимает настройки для своих внутренних парсеров, включая `@typescript-eslint/parser` и `typescript`, что позволяет определить грамматические правила TypeScript в `.vue` файлах.

2. Правило «vue-hooks-internal-state-change»

Создайте новый файл `rules/custom-rules.js` в проекте и настройте его так:

```javascript
const vueHooks = [
  'beforeCreate',
  'created',
  'beforeMount',
  'mounted',
  'beforeUpdate',
  'updated',
  'activated',
  'deactivated',
  'beforeDestroy',
  'destroyed',
];

export default {
  meta: {
    type: 'suggestion',
    docs: {
      description: 'Протестировать изменение внутреннего состояния компонента в обновленных хуках жизненного цикла',
      recommended: true,
    },
    fixable: 'code',
    schema: [],
  },
  create: function(context) {
    return {
      // Обработчики сущностей для проверки в хуках жизненного цикла

      CallExpression(node) {
        const callee = node.callee;

        // Игнорируем вызовы методов из внешних библиотек (например, Vuex)
        //и методы, которые не соответствуют тому, что изменяет внутреннее state компонента (например, alert)
        if (
          !callee.property ||
          node.arguments.length !== 1 ||
          isExternalLibraryCall(callee) ||
          isNoStateChangeMethod(callee.name)
        ) {
          return;
        }

        const changedStateProperty = ([propName]) => {
          const propPath = context.getScope().getStringSeeds().find(
            s => s.kind === 'Property' && s.name.name === propName
          );
          if (!propPath) {
            context.report({
              node,
              message: `Присваивание '${propName}' вне prop или data не является изменением внутреннего состояния компонента`,
            });
          } else {
            const propDef = propPath.parent.parent;

            if (propDef.type !== 'ObjectExpression') {
              context.report({
                node: propDef,
                message:
                  'Внутреннее изменение состояния компонента в данной области скрипта только возможно с помощью данных или пропсов',
              });
              return;
            }

            if (!propDef.properties.some(({key, value}) => {
              if (key.type === 'Identifier' && key.name === propName) {
                if (value.type === 'AssignmentExpression') {
                  const {left, operator, right} = value;
                  if (left.type !== 'MemberExpression') {
                    context.report({
                      node: value,
                      message: `Свойство '${propName}' должно быть присвоено через объекта данных или пропса к компоненту`,
                    });
                    return false;
                  } else if (operator !== '=') {
                    return false;
                  }

                  const {object} = left;
                  return isDataProps(object, context);
                }
              }
              return false;
            })) {
              context.report({
                node,
                message: `Присваивание '${propName}' вне data или пропса не является изменением внутреннего состояния компонента`,
              });
            }
          }
        };

        const argument = node.arguments[0];

        if (argument.type === 'FunctionExpression' || argument.type === 'ArrowFunctionExpression') {
          // Игнорирование вызовов callback-функций без изменений состояния
          context.report({
            node: node.arguments[0],
            message:
              'Вызов с аргументом в виде callback-функции без изменений состояния компонента в данном хуке',
          });
        } else if (argument.type === 'ObjectExpression') {
          // Игнорируем вызовы методов, где аргументом является объект с константами
          // (например, вызовы с пропами без изменений)
          if (isPropsOrComputedParams(argument, context)) {
            return;
          }

          argument.properties.forEach(property => {
            if (property.type === 'Property') {
              changedStateProperty(property.key.name);
            }
          });
        } else if (argument.type === 'Identifier') {
          changedStateProperty(argument.name);
        } else {
          context.report({
            node: argument,
            message: 'Неверный тип аргумента для изменения внутреннего состояния компонента',
          });
        }
      },
    };
  },
};

// Хелперы

function isExternalLibraryCall(callee) {
  const externalLibs = ['map', 'filter', 'slice', 'reduce'];

  return externalLibs.includes(callee.name);
}

function isNoStateChangeMethod(methodName) {
  const noStateChangeMethods = ['preventDefault', 'stopPropagation'];

  return noStateChangeMethods.includes(methodName);
}

function isDataProps(node, context) {
  // Хелпер для проверки, является ли объект данными или пропсами компонента
  const dataProps = [...context.getScope().getStringSeeds().filter(s => s.kind === 'Property'), ...getProps(transaction, node)];

  return dataProps.some(({name, key}) => {
    if (name === undefined || key === undefined) {
      return false;
    }
    if (name === '__vue_props_defined__' && key.name === propsKey) {
      return true;
    }
    return dataProps.includes(`${name}.${key.name}`);
  });
}

function getProps(transaction, node) {
  const result = new Set();

  transaction.walk(node, {
    enter(path) {
      if (path.isObjectProperty()) {
        const {key, value} = path.node;
        if (key.type !== 'Identifier') {
          return;
        }

        if (value && value.type === 'ObjectExpression') {
          path.traverse(
            {
              enter(node) {
                if (node.type === 'Property' && node.key.type === 'Identifier') {
                  const propName = node.key.name;
                  if (!result.has(propName)) {
                    result.add(propName);
                  }
                }
              },
              exit() {
                // exit after visiting all properties
                // so the traversal stops
              },
            },
            value,
          );
        }
      }
    },
  });

  return Array.from(result);
}
```

Соотвествующее правило `vue-hooks-internal-state-change` добавит необходимые проверки в хуках жизненного цикла для предотвращения изменений внутреннего состояния компонента без вызова методов, изменяющих состояние компонента.

3. Хелперы

В приведенном выше файле располагаются несколько хелперов, используемых в правилах `vue-hooks-internal-state-change`.

`isExternalLibraryCall`: проверяет, является ли функция из внешней библиотеки.

`isNoStateChangeMethod`: проверяет, является ли вызываемая функция методом, который не меняет внутреннее состояние компонента.

`isDataProps`: проверяет, является ли объект данными или пропсами компонента.

`getProps`: получает все свойства объектов, используемых в фрагменте шаблона компонента в данном хуке.

