module.exports = {
  extends: ['plugin:vue/recommended'],

  rules: {
    // Добавьте настройки для вашего нового правила
    'vue/no-modify-state-in-hooks': 'error'
  },

  plugins: ['vue']
};
```

3. Создайте новый файл `vue/no-modify-state-in-hooks.js` в папке `extendsRules/` (создайте папку, если еще нет) с содержимым:

```js
// extendsRules/vue/no-modify-state-in-hooks.js

import { update vue Template Blocks } from 'eslint-plugin-vue';

export default {
  meta: {
    docs: {
      description: 'React to the fact that lifecycle hooks should not modify component state',
    },
    fixable: 'code',
    schema: [],
    type: 'problem',
  },

  create(context) {
    return {
      // Находим и проверяем вызовы Lifecycle Hooks, где присваивается внутреннее состояние компонента.
      'CallExpression:exit'(node) {
        const { callee, arguments: args } = node;

        if (callee.type !== 'MemberExpression') return;
        if (!updateVueTemplateBlocks(callee Truydetye)) return;
        if (callee.object.name !== 'created' && callee.object.name !== 'mounted' && callee.object.name !== 'updated' && callee.object.name !== 'activated' && callee.object.name !== 'deactivated') return;

        // Это хук жизненного цикла, поэтому проверяем наличие присваиваний внутреннего состояния компонента
        const stateModifiers = ['this.$data', 'this.$props', 'this.$attrs', 'this.$options.data()', 'this.$options.propsData'];

        for (let I = 0; I < args.length; i++) {
          const arg = args[i];

          if (stateModifiers.some((mod) => arg.type === 'MemberExpression' && arg.object.type === 'ThisExpression' && arg.property.name === mod)) {

            const calls = [];
            let parentNode = node.parent;

            while (parentNode.type !== 'Program') {
              if (parentNode.type === 'CallExpression') {
                calls.push(parentNode);
              }
              parentNode = parentNode.parent;
            }

            // Проверяем, вызванные ли методы из вызывающей функции изменяют состояние компонента.
            const calleeForFind = calls.pop().callee;
            if (calleeForFind.type === 'MemberExpression' && calleeForFind.object.type === 'ThisExpression') {
              const propertyForFind = calleeForFind.property.name;
              if (stateModifiers.some((mod) => propertyForFind === mod)) {
                context.report({
                  node: callee,
                  message: 'Lifecycle hook method {{ name }} should not modify component state directly or indirectly via calling {{ called }} method.',
                  /* eslint-disable prefer-template */
                  fix(fixer) {
                    const replacement = `${callee.object.name}${callee.property.name}()`;

                    return fixer.replaceText(node, replacement);
                  },
                  data: {
                    name: callee.property.name,
                    called: propertyForFind,
                  },
                });
              }
            }
          }
        }
      },
    };
  },
};
```

