   'default' => env('FILESYSTEM_DRIVER', 's3'),
   'links' => [
       public_path('storage') => storage_path('app/public'),
       public_path('disk-synced') => storage_path('framework/disk-synced'),

       // скопируйте и вставьте настройки, если вы используете AWS DynamoDB для тестирования:
